script.setup:
// Matter.js simulates the bodies; a shader draws them as merging blobs (metaballs).
const mod = await ctx.utils.import("https://esm.sh/matter-js@0.20.0");
const M = mod.default ?? mod;
const [w, h] = ctx.resolution;
const W = 1000 * w / h, H = 1000;
const engine = M.Engine.create();
const wall = { isStatic: true };
M.Composite.add(engine.world, [
  M.Bodies.rectangle(W / 2, H + 50, W * 2, 100, wall),
  M.Bodies.rectangle(-50, H / 2, 100, H * 3, wall),
  M.Bodies.rectangle(W + 50, H / 2, 100, H * 3, wall),
  // A tilted shelf the blobs pour over.
  M.Bodies.rectangle(W * 0.35, H * 0.55, W * 0.45, 24, { isStatic: true, angle: 0.25 }),
]);
Object.assign(ctx.state, { M, engine, W, H, balls: [], spawn: 0, data: new Float32Array(270) });
ctx.state.p = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, '#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform vec3 u_balls[90]; uniform int u_count;
uniform vec3 u_colorA; uniform vec3 u_colorB; uniform float u_threshold; uniform vec4 u_shelf;
void main(){
  vec2 p = vec2(v_uv.x * u_resolution.x / u_resolution.y, v_uv.y);
  float field = 0.0; float hue = 0.0;
  for (int i = 0; i < 90; i++) {
    if (i >= u_count) break;
    vec3 b = u_balls[i];
    vec2 d = p - b.xy;
    float f = b.z * b.z / max(dot(d, d), 1e-5);
    field += f; hue += f * fract(float(i) * 0.618);
  }
  hue /= max(field, 1e-5);
  float inside = smoothstep(u_threshold - 0.08, u_threshold + 0.08, field);
  vec3 col = mix(u_colorA, u_colorB, hue);
  vec3 bg = vec3(0.04, 0.045, 0.06) + 0.05 * col * min(field, 1.0);
  vec3 c = mix(bg, col * (0.75 + 0.25 * smoothstep(u_threshold, u_threshold * 3.0, field)), inside);
  // The shelf: a rotated box (center, half length, angle).
  vec2 q = p - u_shelf.xy; float ca = cos(u_shelf.w), sa = sin(u_shelf.w);
  q = vec2(ca * q.x - sa * q.y, sa * q.x + ca * q.y);
  vec2 e = abs(q) - vec2(u_shelf.z, 0.012);
  float shelf = 1.0 - smoothstep(0.0, 0.003, length(max(e, 0.0)) + min(max(e.x, e.y), 0.0));
  outColor = vec4(mix(c, vec3(0.32, 0.34, 0.4), shelf), 1.0);
}');

script.render:
const s = ctx.state, { M } = s, u = ctx.uniforms;
s.engine.gravity.y = u.u_gravity;
s.spawn -= ctx.dt;
if (s.spawn <= 0) {
  s.spawn = 0.12;
  const r = 18 + Math.random() * 26;
  const ball = M.Bodies.circle(s.W * (0.15 + Math.random() * 0.7), -60, r, { restitution: 0.3, friction: 0.02 });
  ball.r = r;
  M.Composite.add(s.engine.world, ball);
  s.balls.push(ball);
  if (s.balls.length > 90) M.Composite.remove(s.engine.world, s.balls.shift());
}
// Hold the mouse button to pull the blobs toward the pointer.
if (ctx.mouseDown) {
  const tx = ctx.mouse[0] * s.W, ty = ctx.mouse[1] * s.H;
  for (const b of s.balls) M.Body.applyForce(b, b.position, { x: (tx - b.position.x) * 2e-6 * b.mass, y: (ty - b.position.y) * 2e-6 * b.mass });
}
M.Engine.update(s.engine, Math.min(ctx.dt, 1 / 30) * 1000);
s.balls.forEach((b, i) => s.data.set([b.position.x / s.H, 1 - b.position.y / s.H, b.r / s.H * 1.1], i * 3));
ctx.gl.useProgram(s.p);
// Matter's y goes down and the shelf's angle turns clockwise on screen.
ctx.utils.drawFullscreen(s.p, { u_balls: s.data, u_count: s.balls.length, u_shelf: [s.W * 0.35 / s.H, 1 - 0.55, s.W * 0.45 / 2 / s.H, 0.25] });
ctx.publish("bodies", s.balls.length);
